/**
 * Stage 4's traffic cars: a small hatchback and a one-box van, photographed
 * from straight above (white cars, cut out of their studio backgrounds).
 *
 * Each car is up to three images drawn one over the other. `detail` is the
 * whole car as photographed, except its glass: the studio photos show the
 * windows nearly black (luminance 20-50), which on the road read as holes
 * and, under a dark paint, merged with the body into one black shape. The
 * glass is lifted and blued, keeping its own detail, with a soft sky
 * reflection across each pane. `paint` is only the bodywork -- every
 * colourless pixel from mid-grey up, the glass excepted, so panel lines
 * and shaded flanks take the colour too (left half-covered, they showed
 * the white photo through as light outlines on a dark car) -- drawn on
 * top with a tint. A tint multiplies, so the white panels take any
 * colour with the photo's own shading kept, and the glass, lamps and tyres
 * underneath stay as they are. One set of textures makes every colour.
 * `gloss` is the bodywork's brightest, specular parts, drawn white over a
 * DARK paint only (see glossFor): multiplied down to black, the body's own
 * shading is gone, and without it a black car is a flat silhouette.
 *
 * `length` is the real car's length in metres (the size it is drawn at is
 * set from it against the player's car, see main.js); `px` the image size
 * and `bodyPx` the width of the body without its mirrors, in image pixels.
 */
export const MOB_CARS = {
  hatch: {
    length: 3.94,
    px: { w: 218, h: 400 },
    bodyPx: 180,
    detail: "data:image/png;base64,",
    gloss: "data:image/png;base64,",
    paint: "data:image/png;base64,",
  },
  van: {
    length: 4.695,
    px: { w: 180, h: 400 },
    bodyPx: 152,
    detail: "data:image/png;base64,",
    gloss: "data:image/png;base64,",
    paint: "data:image/png;base64,",
  },
};

/** How much of the gloss layer a paint gets: none on light colours, up to
 *  0.35 on black. */
export function glossFor(paint) {
  const lum = (0.299 * ((paint >> 16) & 255) + 0.587 * ((paint >> 8) & 255) + 0.114 * (paint & 255)) / 255;
  return 0.35 * Math.max(0, 0.55 - lum) / 0.55;
}

/** Body colours, picked at random per car: mostly the whites, silvers and
 *  blacks real traffic is made of, with some colour among them. */
export const MOB_PAINTS = [
  0xf4f4f2, 0xf4f4f2, 0xe9e4d4,   // white, pearl
  0xbfc3c8, 0xbfc3c8, 0x7a7f86,   // silver, grey
  0x2b2d31, 0x2b2d31,             // black
  0xc2282b, 0x2758b4, 0x1e2b4c,   // red, blue, navy
  0xe3b322, 0x2f6b46, 0x8a1f2a,   // yellow, green, wine
];
